package ma.ebank.ebank;
import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException; import org.springframework.http.HttpStatus; import java.math.BigDecimal; import java.util.UUID;
@Service public class BankService {
final AccountRepository accounts; final OperationRepository operations; final CustomerLookup customers;
public BankService(AccountRepository a,OperationRepository o,CustomerLookup c){accounts=a;operations=o;customers=c;}
BankAccount get(String id){return accounts.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Compte introuvable"));}
BankAccount lock(String id){return accounts.locked(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Compte introuvable"));}
public BankAccount create(Long customerId,BankAccount.AccountType type,String agency){if(customers.find(customerId)==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Client introuvable");BankAccount a=new BankAccount();a.id=UUID.randomUUID().toString();a.ribReference="DEMO-"+a.id;a.customerId=customerId;a.type=type;a.agency=agency;a.balance=new BigDecimal("0.00");return accounts.save(a);}
void apply(BankAccount a,BigDecimal amount,boolean credit,String ref,String desc){if(!"ACTIVE".equals(a.status))throw new ResponseStatusException(HttpStatus.CONFLICT,"Compte inactif");if(amount==null||amount.signum()<=0||amount.scale()>2)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Montant invalide");if(!credit&&a.balance.compareTo(amount)<0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Solde insuffisant");a.balance=credit?a.balance.add(amount):a.balance.subtract(amount);BankOperation o=new BankOperation();o.accountId=a.id;o.amount=amount;o.type=credit?"CREDIT":"DEBIT";o.reference=ref;o.description=desc;operations.save(o);}
@Transactional public BankAccount move(String id,BigDecimal amount,boolean credit,String desc){BankAccount a=lock(id);apply(a,amount,credit,UUID.randomUUID().toString(),desc);return a;}
@Transactional public String transfer(String from,String to,BigDecimal amount){if(from.equals(to))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Comptes identiques");BankAccount first=lock(from.compareTo(to)<0?from:to);BankAccount second=lock(from.compareTo(to)<0?to:from);BankAccount a=first.id.equals(from)?first:second;BankAccount b=first.id.equals(to)?first:second;String ref=UUID.randomUUID().toString();apply(a,amount,false,ref,"Virement sortant");apply(b,amount,true,ref,"Virement entrant");return ref;}
}